['min_range' => 1]] ) === false ) { return $default; } return (int) $value; } /* ============================================================ URL / SLUG HELPERS ============================================================ */ /** * Create an SEO-friendly slug. */ function slugify(string $text): string { $text = trim($text); if ($text === '') { return ''; } // Transliterate Unicode where iconv is available. if (function_exists('iconv')) { $converted = @iconv( 'UTF-8', 'ASCII//TRANSLIT//IGNORE', $text ); if ($converted !== false) { $text = $converted; } } $text = strtolower($text); $text = preg_replace( '/[^a-z0-9]+/', '-', $text ) ?? ''; return trim($text, '-'); } /** * Validate a stored slug. */ function valid_slug(string $slug): bool { return (bool) preg_match( '/^[a-z0-9]+(?:-[a-z0-9]+)*$/', $slug ); } /* ============================================================ CLIENT INFORMATION ============================================================ */ /** * Get visitor IP address. * * REMOTE_ADDR is intentionally preferred. * * We do not blindly trust X-Forwarded-For because it can be * spoofed unless the application is explicitly configured * behind a trusted proxy. */ function client_ip(): string { $ip = $_SERVER['REMOTE_ADDR'] ?? ''; if ( is_string($ip) && filter_var($ip, FILTER_VALIDATE_IP) ) { return $ip; } return '0.0.0.0'; } /** * Return a safely limited user-agent value. */ function user_agent(): string { $agent = $_SERVER['HTTP_USER_AGENT'] ?? ''; if (!is_string($agent)) { return ''; } return mb_substr($agent, 0, 500); } /* ============================================================ SESSION ============================================================ */ /** * Start the secure application session. * * Cookie/security configuration is defined in config.php. */ function start_secure_session(): void { if (session_status() === PHP_SESSION_NONE) { session_start(); } enforce_session_timeout(); } /** * Enforce idle and absolute admin session limits. */ function enforce_session_timeout(): void { if (session_status() !== PHP_SESSION_ACTIVE) { return; } if (empty($_SESSION['admin_id'])) { return; } $now = time(); $createdAt = (int) ($_SESSION['session_created_at'] ?? $now); $lastActivity = (int) ($_SESSION['last_activity'] ?? $now); $idleExpired = ($now - $lastActivity) > SESSION_IDLE_TIMEOUT; $absoluteExpired = ($now - $createdAt) > SESSION_MAX_LIFETIME; if ($idleExpired || $absoluteExpired) { logout_admin_session(); return; } $_SESSION['last_activity'] = $now; } /** * Destroy the current admin session securely. */ function logout_admin_session(): void { if (session_status() !== PHP_SESSION_ACTIVE) { return; } $_SESSION = []; if (ini_get('session.use_cookies')) { $params = session_get_cookie_params(); setcookie( session_name(), '', [ 'expires' => time() - 42000, 'path' => $params['path'] ?: '/', 'domain' => $params['domain'] ?? '', 'secure' => (bool) ($params['secure'] ?? false), 'httponly' => (bool) ($params['httponly'] ?? true), 'samesite' => $params['samesite'] ?? 'Lax', ] ); } session_destroy(); } /* ============================================================ CSRF PROTECTION ============================================================ */ /** * Generate or retrieve a CSRF token. */ function csrf_token(): string { start_secure_session(); $createdAt = (int) ($_SESSION['csrf_created_at'] ?? 0); $expired = $createdAt === 0 || (time() - $createdAt) > CSRF_TOKEN_LIFETIME; if ( empty($_SESSION['csrf_token']) || !is_string($_SESSION['csrf_token']) || $expired ) { $_SESSION['csrf_token'] = bin2hex( random_bytes(32) ); $_SESSION['csrf_created_at'] = time(); } return $_SESSION['csrf_token']; } /** * Generate hidden CSRF input field. */ function csrf_field(): string { return ''; } /** * Validate a submitted CSRF token. */ function verify_csrf_token(?string $token): bool { start_secure_session(); if ( empty($token) || empty($_SESSION['csrf_token']) || !is_string($_SESSION['csrf_token']) ) { return false; } $createdAt = (int) ($_SESSION['csrf_created_at'] ?? 0); if ( $createdAt === 0 || (time() - $createdAt) > CSRF_TOKEN_LIFETIME ) { unset( $_SESSION['csrf_token'], $_SESSION['csrf_created_at'] ); return false; } return hash_equals( $_SESSION['csrf_token'], $token ); } /** * Require valid CSRF token for POST requests. */ function require_csrf(): void { if (!is_post()) { return; } $token = post_string('csrf_token'); if (!verify_csrf_token($token)) { http_response_code(419); exit( 'Your session has expired. Please refresh the page and try again.' ); } } /* ============================================================ FLASH MESSAGES ============================================================ */ /** * Store a one-time flash message. */ function flash( string $type, string $message ): void { start_secure_session(); $allowed = [ 'success', 'error', 'warning', 'info', ]; if (!in_array($type, $allowed, true)) { $type = 'info'; } $_SESSION['flash'][] = [ 'type' => $type, 'message' => $message, ]; } /** * Retrieve and remove flash messages. */ function get_flash_messages(): array { start_secure_session(); $messages = $_SESSION['flash'] ?? []; unset($_SESSION['flash']); return is_array($messages) ? $messages : []; } /* ============================================================ SETTINGS ============================================================ */ /** * Retrieve a website setting. */ function setting( string $key, ?string $default = null ): ?string { static $cache = []; if (array_key_exists($key, $cache)) { return $cache[$key]; } try { $stmt = db()->prepare( 'SELECT setting_value FROM settings WHERE setting_key = :setting_key LIMIT 1' ); $stmt->execute([ 'setting_key' => $key, ]); $value = $stmt->fetchColumn(); if ($value === false) { $cache[$key] = $default; return $default; } $cache[$key] = (string) $value; return $cache[$key]; } catch (Throwable $exception) { error_log( 'Setting lookup failed: ' . $exception->getMessage() ); return $default; } } /** * Insert or update a setting. */ function update_setting( string $key, ?string $value ): bool { if ($key === '') { return false; } try { $stmt = db()->prepare( 'INSERT INTO settings (setting_key, setting_value) VALUES (:setting_key, :setting_value) ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)' ); return $stmt->execute([ 'setting_key' => $key, 'setting_value' => $value, ]); } catch (Throwable $exception) { error_log( 'Setting update failed: ' . $exception->getMessage() ); return false; } } /** * Convert a setting to boolean. */ function setting_bool( string $key, bool $default = false ): bool { $value = setting( $key, $default ? '1' : '0' ); return in_array( strtolower((string) $value), ['1', 'true', 'yes', 'on'], true ); } /* ============================================================ ADMIN AUTHENTICATION / ROLES ============================================================ */ /** * Check whether an administrator is logged in. */ function admin_logged_in(): bool { start_secure_session(); return !empty($_SESSION['admin_id']) && positive_int($_SESSION['admin_id']) > 0; } /** * Return logged-in admin ID. */ function current_admin_id(): ?int { if (!admin_logged_in()) { return null; } return positive_int( $_SESSION['admin_id'] ) ?: null; } /** * Return logged-in administrator data. */ function current_admin(): ?array { static $cachedAdmin = null; static $loaded = false; if ($loaded) { return $cachedAdmin; } $loaded = true; $adminId = current_admin_id(); if ($adminId === null) { return null; } try { $stmt = db()->prepare( 'SELECT id, name, email, role, status, last_login, created_at, updated_at FROM admins WHERE id = :id LIMIT 1' ); $stmt->execute([ 'id' => $adminId, ]); $admin = $stmt->fetch(); if ( !$admin || $admin['status'] !== 'active' ) { logout_admin_session(); return null; } $cachedAdmin = $admin; return $cachedAdmin; } catch (Throwable $exception) { error_log( 'Current admin lookup failed: ' . $exception->getMessage() ); return null; } } /** * Check whether logged-in administrator has one of the roles. */ function admin_has_role( string|array $roles ): bool { $admin = current_admin(); if (!$admin) { return false; } $roles = (array) $roles; return in_array( $admin['role'], $roles, true ); } /** * Check a reusable permission. */ function admin_can(string $permission): bool { $admin = current_admin(); if (!$admin) { return false; } $role = $admin['role']; if ($role === 'super_admin') { return true; } $permissions = [ 'admin' => [ 'dashboard.view', 'tools.view', 'tools.create', 'tools.edit', 'tools.delete', 'categories.view', 'categories.create', 'categories.edit', 'categories.delete', 'pages.view', 'pages.create', 'pages.edit', 'pages.delete', 'announcements.view', 'announcements.create', 'announcements.edit', 'announcements.delete', 'seo.view', 'seo.edit', 'branding.view', 'settings.view', ], 'editor' => [ 'dashboard.view', 'tools.view', 'tools.create', 'tools.edit', 'categories.view', 'pages.view', 'pages.create', 'pages.edit', 'announcements.view', 'announcements.create', 'announcements.edit', ], ]; return in_array( $permission, $permissions[$role] ?? [], true ); } /** * Require an administrator permission. */ function require_admin_permission( string $permission ): void { if (!admin_logged_in()) { redirect(ADMIN_URL . '/login.php'); } if (!admin_can($permission)) { http_response_code(403); exit( 'You do not have permission to perform this action.' ); } } /* ============================================================ AUDIT LOG ============================================================ */ /** * Record an administrator action. */ function audit_log( string $action, ?string $entityType = null, ?int $entityId = null ): void { try { $stmt = db()->prepare( 'INSERT INTO audit_logs ( admin_id, action, entity_type, entity_id, ip_address, user_agent ) VALUES ( :admin_id, :action, :entity_type, :entity_id, :ip_address, :user_agent )' ); $stmt->execute([ 'admin_id' => current_admin_id(), 'action' => mb_substr( $action, 0, 150 ), 'entity_type' => $entityType !== null ? mb_substr($entityType, 0, 100) : null, 'entity_id' => $entityId, 'ip_address' => client_ip(), 'user_agent' => user_agent(), ]); } catch (Throwable $exception) { // Audit failure must not crash the website. error_log( 'Audit log failed: ' . $exception->getMessage() ); } } /* ============================================================ LOGIN RATE LIMITING ============================================================ */ /** * Record a login attempt. */ function record_login_attempt( string $email, bool $successful ): void { try { $stmt = db()->prepare( 'INSERT INTO login_attempts ( email, ip_address, successful, attempted_at ) VALUES ( :email, :ip_address, :successful, NOW() )' ); $stmt->execute([ 'email' => mb_strtolower( trim($email) ), 'ip_address' => client_ip(), 'successful' => $successful ? 1 : 0, ]); } catch (Throwable $exception) { error_log( 'Unable to record login attempt: ' . $exception->getMessage() ); } } /** * Determine whether a login should currently be blocked. * * Failed attempts are checked against both IP address and email. */ function login_rate_limited( string $email ): bool { $email = mb_strtolower( trim($email) ); $cutoff = date( 'Y-m-d H:i:s', time() - LOGIN_ATTEMPT_WINDOW ); try { $stmt = db()->prepare( 'SELECT COUNT(*) FROM login_attempts WHERE successful = 0 AND attempted_at >= :cutoff AND ( ip_address = :ip_address OR email = :email )' ); $stmt->execute([ 'cutoff' => $cutoff, 'ip_address' => client_ip(), 'email' => $email, ]); return (int) $stmt->fetchColumn() >= MAX_LOGIN_ATTEMPTS; } catch (Throwable $exception) { error_log( 'Login rate-limit check failed: ' . $exception->getMessage() ); /* * Do not permanently lock administrators out if the * rate-limit table temporarily fails. */ return false; } } /* ============================================================ TOOL MODULE REGISTRY ============================================================ */ /** * Trusted calculator module registry. * * Admins may select only these module identifiers. * * Never include a module using arbitrary user/database input. */ function tool_modules(): array { return [ 'age-calculator' => [ 'name' => 'Age Calculator', 'file' => 'age-calculator.php', ], 'percentage-calculator' => [ 'name' => 'Percentage Calculator', 'file' => 'percentage-calculator.php', ], 'negative-marking-calculator' => [ 'name' => 'Negative Marking Calculator', 'file' => 'negative-marking-calculator.php', ], 'date-difference-calculator' => [ 'name' => 'Date Difference Calculator', 'file' => 'date-difference-calculator.php', ], 'exam-countdown' => [ 'name' => 'Exam Countdown', 'file' => 'exam-countdown.php', ], 'emi-calculator' => [ 'name' => 'EMI Calculator', 'file' => 'emi-calculator.php', ], 'simple-interest-calculator' => [ 'name' => 'Simple Interest Calculator', 'file' => 'simple-interest-calculator.php', ], 'compound-interest-calculator' => [ 'name' => 'Compound Interest Calculator', 'file' => 'compound-interest-calculator.php', ], 'discount-calculator' => [ 'name' => 'Discount Calculator', 'file' => 'discount-calculator.php', ], 'gst-calculator' => [ 'name' => 'GST Calculator', 'file' => 'gst-calculator.php', ], 'word-counter' => [ 'name' => 'Word Counter', 'file' => 'word-counter.php', ], 'character-counter' => [ 'name' => 'Character Counter', 'file' => 'character-counter.php', ], 'case-converter' => [ 'name' => 'Case Converter', 'file' => 'case-converter.php', ], 'password-generator' => [ 'name' => 'Password Generator', 'file' => 'password-generator.php', ], 'da-calculator' => [ 'name' => 'DA Calculator', 'file' => 'da-calculator.php', ], 'hra-calculator' => [ 'name' => 'HRA Calculator', 'file' => 'hra-calculator.php', ], 'nps-calculator' => [ 'name' => 'NPS Calculator', 'file' => 'nps-calculator.php', ], ]; } /** * Check whether a tool module is registered. */ function valid_tool_module(string $module): bool { return array_key_exists( $module, tool_modules() ); } /** * Return safe filesystem path for registered module. */ function tool_module_path( string $module ): ?string { $modules = tool_modules(); if (!isset($modules[$module])) { return null; } $file = MODULES_PATH . DIRECTORY_SEPARATOR . $modules[$module]['file']; if (!is_file($file)) { return null; } return $file; } /* ============================================================ TOOLS / CATEGORIES ============================================================ */ /** * Retrieve a published tool by slug. */ function get_tool_by_slug( string $slug ): ?array { if (!valid_slug($slug)) { return null; } try { $stmt = db()->prepare( 'SELECT t.*, c.name AS category_name, c.slug AS category_slug FROM tools t LEFT JOIN categories c ON c.id = t.category_id WHERE t.slug = :slug AND t.status = "published" LIMIT 1' ); $stmt->execute([ 'slug' => $slug, ]); $tool = $stmt->fetch(); return $tool ?: null; } catch (Throwable $exception) { error_log( 'Tool lookup failed: ' . $exception->getMessage() ); return null; } } /** * Retrieve active categories. */ function active_categories(): array { try { $stmt = db()->query( 'SELECT id, name, slug, icon, description, sort_order FROM categories WHERE status = "active" ORDER BY sort_order ASC, name ASC' ); return $stmt->fetchAll(); } catch (Throwable $exception) { error_log( 'Category lookup failed: ' . $exception->getMessage() ); return []; } } /** * Retrieve published tools. */ function published_tools( int $limit = 20 ): array { $limit = max( 1, min($limit, 100) ); try { $sql = 'SELECT t.*, c.name AS category_name, c.slug AS category_slug FROM tools t LEFT JOIN categories c ON c.id = t.category_id WHERE t.status = "published" ORDER BY t.popular DESC, t.featured DESC, t.updated_at DESC LIMIT ' . $limit; return db()->query($sql)->fetchAll(); } catch (Throwable $exception) { error_log( 'Published tool lookup failed: ' . $exception->getMessage() ); return []; } } /* ============================================================ PAGES ============================================================ */ /** * Retrieve a published page by slug. */ function get_page_by_slug( string $slug ): ?array { if (!valid_slug($slug)) { return null; } try { $stmt = db()->prepare( 'SELECT * FROM pages WHERE slug = :slug AND status = "published" LIMIT 1' ); $stmt->execute([ 'slug' => $slug, ]); $page = $stmt->fetch(); return $page ?: null; } catch (Throwable $exception) { error_log( 'Page lookup failed: ' . $exception->getMessage() ); return null; } } /* ============================================================ ADS ============================================================ */ /** * Render an enabled ad placement. * * IMPORTANT: * ad_code is intentionally returned as trusted raw HTML/JS. * Access to editing this field must be restricted to trusted * administrator roles. */ function render_ad(string $placement): string { if (!setting_bool('ads_enabled')) { return ''; } try { $stmt = db()->prepare( 'SELECT ad_code FROM ads WHERE placement = :placement AND status = "active" LIMIT 1' ); $stmt->execute([ 'placement' => $placement, ]); $code = $stmt->fetchColumn(); if ( $code === false || trim((string) $code) === '' ) { return ''; } return '

' . (string) $code . '

'; } catch (Throwable $exception) { error_log( 'Advertisement lookup failed: ' . $exception->getMessage() ); return ''; } } /* ============================================================ ANNOUNCEMENTS ============================================================ */ /** * Return currently active announcement. */ function active_announcement(): ?array { try { $stmt = db()->query( 'SELECT id, message, link, start_at, end_at FROM announcements WHERE status = "active" AND ( start_at IS NULL OR start_at = NOW() ) ORDER BY id DESC LIMIT 1' ); $announcement = $stmt->fetch(); return $announcement ?: null; } catch (Throwable $exception) { error_log( 'Announcement lookup failed: ' . $exception->getMessage() ); return null; } } /* ============================================================ FILE UPLOAD SECURITY ============================================================ */ /** * Upload a trusted branding image securely. * * Returns: * [ * 'success' => bool, * 'filename' => string|null, * 'error' => string|null * ] */ function upload_image(array $file): array { if ( !isset( $file['error'], $file['tmp_name'], $file['size'] ) ) { return [ 'success' => false, 'filename' => null, 'error' => 'Invalid upload.', ]; } if ((int) $file['error'] !== UPLOAD_ERR_OK) { return [ 'success' => false, 'filename' => null, 'error' => 'The file could not be uploaded.', ]; } if ( (int) $file['size'] MAX_UPLOAD_SIZE ) { return [ 'success' => false, 'filename' => null, 'error' => 'The image exceeds the allowed file size.', ]; } if (!is_uploaded_file($file['tmp_name'])) { return [ 'success' => false, 'filename' => null, 'error' => 'Invalid uploaded file.', ]; } $finfo = new finfo(FILEINFO_MIME_TYPE); $mime = $finfo->file( $file['tmp_name'] ); $allowed = [ 'image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp', 'image/gif' => 'gif', ]; if ( !is_string($mime) || !isset($allowed[$mime]) ) { return [ 'success' => false, 'filename' => null, 'error' => 'Only JPG, PNG, WebP and GIF images are allowed.', ]; } /* * Confirm that PHP can identify the uploaded content * as an actual image. */ if (@getimagesize($file['tmp_name']) === false) { return [ 'success' => false, 'filename' => null, 'error' => 'The uploaded file is not a valid image.', ]; } if (!is_dir(UPLOAD_PATH)) { if ( !mkdir( UPLOAD_PATH, 0755, true ) && !is_dir(UPLOAD_PATH) ) { return [ 'success' => false, 'filename' => null, 'error' => 'Upload directory is unavailable.', ]; } } $filename = bin2hex( random_bytes(16) ) . '.' . $allowed[$mime]; $destination = UPLOAD_PATH . DIRECTORY_SEPARATOR . $filename; if ( !move_uploaded_file( $file['tmp_name'], $destination ) ) { return [ 'success' => false, 'filename' => null, 'error' => 'Unable to save the uploaded image.', ]; } @chmod($destination, 0644); return [ 'success' => true, 'filename' => $filename, 'error' => null, ]; } /* ============================================================ PASSWORD VALIDATION ============================================================ */ /** * Validate strong administrator password. */ function validate_admin_password( string $password ): array { $errors = []; if (strlen($password) < 10) { $errors[] = 'Password must contain at least 10 characters.'; } if (!preg_match('/[A-Z]/', $password)) { $errors[] = 'Password must contain at least one uppercase letter.'; } if (!preg_match('/[a-z]/', $password)) { $errors[] = 'Password must contain at least one lowercase letter.'; } if (!preg_match('/[0-9]/', $password)) { $errors[] = 'Password must contain at least one number.'; } if ( !preg_match( '/[^A-Za-z0-9]/', $password ) ) { $errors[] = 'Password must contain at least one special character.'; } return $errors; } /* ============================================================ HTML SANITIZATION ============================================================ */ /** * Basic HTML sanitizer for admin-managed page content. * * This intentionally supports a conservative HTML subset. * * It is NOT intended for arbitrary untrusted public HTML. */ function sanitize_content_html( string $html ): string { $allowedTags = '


' . '

' . '

' . '

' . ''; $html = strip_tags( $html, $allowedTags ); /* * Remove event-handler attributes such as: * onclick, onerror, onload, etc. */ $html = preg_replace( '/\s+on[a-z]+\s*=\s*(".*?"|\'.*?\'|[^\s>]+)/i', '', $html ) ?? ''; /* * Remove javascript: URLs. */ $html = preg_replace( '/javascript\s*:/i', '', $html ) ?? ''; /* * Remove data: URLs from content. */ $html = preg_replace( '/data\s*:/i', '', $html ) ?? ''; return trim($html); } /* ============================================================ MAINTENANCE MODE ============================================================ */ /** * Determine whether public maintenance mode is active. */ function maintenance_mode_active(): bool { return setting_bool( 'maintenance_mode', false ); } /* ============================================================ SEO HELPERS ============================================================ */ /** * Create a safe meta description. */ function meta_description( ?string $description, int $maxLength = 160 ): string { $description = trim( strip_tags((string) $description) ); $description = preg_replace( '/\s+/', ' ', $description ) ?? ''; if ( mb_strlen($description) > $maxLength ) { $description = mb_substr( $description, 0, $maxLength - 1 ) . '…'; } return $description; } /** * Return site name. */ function site_name(): string { return setting( 'site_name', APP_NAME ) ?: APP_NAME; } /** * Build a page title. */ function page_title( ?string $title = null ): string { $siteName = site_name(); if ( $title === null || trim($title) === '' ) { return setting( 'default_seo_title', $siteName ) ?: $siteName; } return trim($title); }
